// Generated from tenants/customer-a/fields.yaml — do not edit by hand.
// klaxon-mask-customer-a: deterministic masking for klaxon-masked-customer-a-v5-*.
def HEX = "0123456789abcdef";
def SALT = params.salt;  // injected as the script processor's params.salt
def TOKEN_RE = Pattern.compile("^\\[(?:IP|USER|HOST|AGENT)_[0-9a-f]{16}\\]$");

String hex16(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < 8; i++) {
        int b = bytes[i] & 0xff;
        sb.append(HEX.charAt(b >> 4));
        sb.append(HEX.charAt(b & 0x0f));
    }
    return sb.toString();
}

String sha256hex(String input) {
    MessageDigest md = MessageDigest.getInstance("SHA-256");
    return hex16(md.digest(input.getBytes("UTF-8")));
}

String token(String family, String value) {
    if (value == null) return value;
    if (value.isEmpty()) return value;  // empty stays empty, mirrors derive_token
    if (TOKEN_RE.matcher(value).matches()) return value;  // idempotent
    return "[" + family + "_" + sha256hex(family + ":" + value + ":" + SALT) + "]";
}

String maskPattern(Pattern p, String text, String family) {
    if (text == null) return text;
    Matcher m = p.matcher(text);
    int last = 0;
    StringBuilder out = new StringBuilder();
    while (m.find()) {
        out.append(text.substring(last, m.start()));
        out.append(token(family, m.group(1) == null ? m.group(0) : m.group(1)));
        last = m.end();
    }
    out.append(text.substring(last));
    return out.toString();
}

String maskRegistry(String text, Map source) {
    if (text == null) return text;
    String out = text;
    for (def entry : FIELDS) {
        if (entry[1] != "USER") continue;
        String f = entry[0];
        if (!source.containsKey(f)) continue;
        def v = source.get(f);
        List vals = new ArrayList();
        if (v instanceof List) { for (item in v) { if (item instanceof String) vals.add(item); } }
        else if (v instanceof String) vals.add(v);
        for (raw in vals) {
            String rawStr = (String) raw;
            if (rawStr.length() < 2) continue;
            String tok = token("USER", rawStr);
            if (tok == rawStr) continue; // already a token, nothing to do
            Pattern p = Pattern.compile("(?<![\\w])" + Pattern.quote(rawStr) + "(?![\\w])");
            Matcher m = p.matcher(out);
            int last = 0;
            StringBuilder sb = new StringBuilder();
            while (m.find()) {
                sb.append(out.substring(last, m.start()));
                sb.append(tok);
                last = m.end();
            }
            sb.append(out.substring(last));
            out = sb.toString();
        }
    }
    return out;
}

String maskFreeText(String text, Map source) {
    if (text == null) return text;
    String out = text;
    // Known identities first, so free text reuses the exact structured token.
    out = maskRegistry(out, source);
        out = maskPattern(EMAIL, out, "EMAIL");
        out = maskPattern(IPV6, out, "IP");
        out = maskPattern(IPV4, out, "IP");
        out = maskPattern(USER_NOUN, out, "USER");
        out = maskPattern(USER_AUTH, out, "USER");
        out = maskPattern(UID_EQ, out, "USER");
        out = maskPattern(FOR_USER, out, "USER");
        out = maskPattern(SSH_PUBKEY, out, "USER");
        out = maskPattern(UID_PAREN, out, "USER");
    return out;
}

// Field table injected from fields.yaml — the field list lives there, not here.
def FIELDS = [
    ["destination.ip", "IP", false],
    ["source.ip", "IP", false],
    ["source.address", "IP", false],
    ["user.name", "USER", false],
    ["user.id", "USER", false],
    ["user.effective.name", "USER", false],
    ["client.user.name", "USER", false],
    ["host.hostname", "HOST", false],
    ["source.domain", "HOST", false],
    ["url.domain", "HOST", false],
    ["event.dataset", "HOST", false],
    ["log.logger", "HOST", false],
    ["wazuh.agent.id", "AGENT", false],
    ["wazuh.agent.name", "HOST", false],
    ["wazuh.agent.host.hostname", "HOST", false],
    ["event.original", "USER", false],
    ["related.ip", "IP", true],
    ["related.user", "USER", true],
    ["related.hosts", "HOST", true]
];
def FREE_TEXT = [
    "message"
];

// Free-text regexes, compiled once. The free-text pass references these Pattern
// symbols by name, so the declarations MUST be emitted or the script fails to
// compile at ingest time (and every document is flagged klaxon.masking_error).
    Pattern EMAIL = Pattern.compile("(?i)\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}\\b");
    Pattern IPV6 = Pattern.compile("(?i)\\b(?:[0-9a-fA-F]{1,4}:){2,7}[0-9a-fA-F]{0,4}\\b");
    Pattern IPV4 = Pattern.compile("(?i)\\b(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])(?:\\.(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])){3}\\b");
    Pattern USER_NOUN = Pattern.compile("(?i)\\b(?:user|username|user[-_ ]?name|account)\\b\\s*(?:name)?\\s*[:=]\\s*(?:\\\"|'|`)?([\\w.@%+=-]{2,64})");
    Pattern USER_AUTH = Pattern.compile("(?i)\\b(?:login|logon|sign[- ]?in|authenticat(?:e|ed|ion))\\b\\s+(?:as|for|by)\\s+(?:\\buser\\b\\s+)?([\\w.@%+=-]{2,64})\\b");
    Pattern UID_EQ = Pattern.compile("(?i)\\buid\\s*=\\s*([^\\W\\d_][\\w.@%+=-]{1,63})\\b");
    Pattern FOR_USER = Pattern.compile("(?i)\\b(?:for|by)\\s+user\\s+([\\w.@%+=-]{2,64})\\b");
    Pattern SSH_PUBKEY = Pattern.compile("(?i)\\bAccepted\\s+publickey\\s+for\\s+([\\w.@%+=-]{2,64})\\b");
    Pattern UID_PAREN = Pattern.compile("(?i)\\b(?:by|as|for)\\s+([\\w.@%+=-]{2,64})\\s*\\(\\s*uid\\s*=\\s*\\d+\\s*\\)");

Map masked = new HashMap();
for (key in ctx['_source'].keySet()) { masked.put(key, ctx['_source'].get(key)); }

for (def entry : FIELDS) {
    String f = entry[0];
    String family = entry[1];
    boolean array = entry[2];
    if (!masked.containsKey(f)) continue;            // missing field: no-op
    def v = masked.get(f);
    if (array) {
        if (v instanceof List) {
            List out = new ArrayList();
            for (item in v) {
                if (item instanceof String) out.add(token(family, item));
                else out.add(item);
            }
            masked.put(f, out);
        }
    } else {
        if (v instanceof String) masked.put(f, token(family, v));
    }
}

for (f in FREE_TEXT) {
    if (masked.containsKey(f) && masked.get(f) instanceof String) {
        // Registry reads the RAW original source: free text must re-tokenise the
        // same raw username to the exact structured token.
        masked.put(f, maskFreeText(masked.get(f), ctx['_source']));
    }
}

// Commit atomically: only on full success does _source change. A failure is
// caught by the on_failure processor, which flags klaxon.masking_error and keeps
// the (original) document so it can be filtered and fixed.
ctx['_source'].clear();
ctx['_source'].putAll(masked);
